Here's the complete solution — only the message `<div>` block changes, adding a counter below the textarea:

```tsx
"use client"

import { useState } from "react"
import { SectionSep } from "@/components/ui/SectionHeader"
import { PROFILE } from "@/lib/content"

const META = [
  { label: "Email",        value: PROFILE.socials.email },
  { label: "Role",         value: "AI + Full-stack"     },
  { label: "Availability", value: PROFILE.status        },
  { label: "Response",     value: "Within 24 hours"     },
]

const MESSAGE_MAX = 500

export function ContactSection() {
  const [form, setForm] = useState({ name: "", email: "", message: "" })
  const [status, setStatus] = useState<"idle" | "loading" | "success" | "error">("idle")

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setStatus("loading")
    try {
      const res = await fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      })
      if (res.ok) { setStatus("success"); setForm({ name: "", email: "", message: "" }) }
      else setStatus("error")
    } catch { setStatus("error") }
  }

  const inputStyle: React.CSSProperties = {
    width: "100%",
    minHeight: 46,
    border: "1px solid var(--border-default)",
    borderRadius: "var(--radius-sm)",
    background: "var(--bg)",
    color: "var(--text-primary)",
    padding: "12px 13px",
    fontSize: 14,
    outline: "none",
    fontFamily: "var(--font-sans)",
    transition: "border-color 180ms var(--ease-standard), background 180ms var(--ease-standard), box-shadow 180ms var(--ease-standard)",
    boxSizing: "border-box",
  }

  function onFocus(e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) {
    e.currentTarget.style.borderColor = "var(--border-hover)"
    e.currentTarget.style.background = "var(--surface-2)"
    e.currentTarget.style.boxShadow = "0 0 0 3px rgba(255,255,255,0.055)"
  }
  function onBlur(e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) {
    e.currentTarget.style.borderColor = "var(--border-default)"
    e.currentTarget.style.background = "var(--bg)"
    e.currentTarget.style.boxShadow = "none"
  }

  const charsRemaining = MESSAGE_MAX - form.message.length
  const isOverLimit = charsRemaining < 0

  return (
    <section id="contact" className="section">
      <SectionSep number="08" label="Contact" />
      <div className="section-content">
        <h2 className="section-title">Let&apos;s Build Something</h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 0.9fr) minmax(380px, 1.1fr)",
            gap: 16,
            alignItems: "start",
          }}
        >
          {/* Left — meta */}
          <div>
            <p style={{ fontSize: 15, color: "var(--text-secondary)", lineHeight: 1.7, margin: "0 0 28px" }}>
              Have an AI system, backend workflow, or project in mind? Send me a note.
            </p>

            {/* 2×2 meta grid */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 10,
              }}
            >
              {META.map(({ label, value }) => (
                <div
                  key={label}
                  style={{
                    border: "1px solid var(--border-default)",
                    borderRadius: "var(--radius-md)",
                    background: "var(--surface-1)",
                    padding: 16,
                  }}
                >
                  <p style={{ fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", margin: "0 0 6px" }}>
                    {label}
                  </p>
                  <p style={{ fontSize: 13, color: "var(--text-secondary)", margin: 0 }}>{value}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Right — form */}
          <div
            style={{
              border: "1px solid var(--border-default)",
              borderRadius: "var(--radius-lg)",
              background: "var(--surface-1)",
              padding: 24,
            }}
          >
            {status === "success" ? (
              <div style={{ textAlign: "center", padding: "40px 0" }}>
                <p style={{ fontSize: 28, margin: "0 0 12px" }}>✓</p>
                <p style={{ fontSize: 15, color: "var(--text-primary)", margin: "0 0 6px", fontWeight: 500 }}>Message sent</p>
                <p style={{ fontSize: 13, color: "var(--text-muted)", margin: 0 }}>I&apos;ll get back to you within 24 hours.</p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                  <div>
                    <label style={{ display: "block", fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>Name</label>
                    <input type="text" required value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder="Your name" style={inputStyle} onFocus={onFocus} onBlur={onBlur} />
                  </div>
                  <div>
                    <label style={{ display: "block", fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>Email</label>
                    <input type="email" required value={form.email} onChange={e => setForm(f => ({ ...f, email: e.target.value }))} placeholder="you@email.com" style={inputStyle} onFocus={onFocus} onBlur={onBlur} />
                  </div>
                </div>
                <div>
                  <label style={{ display: "block", fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>Message</label>
                  <textarea
                    required value={form.message}
                    onChange={e => setForm(f => ({ ...f, message: e.target.value }))}
                    placeholder="Tell me about your project..."
                    rows={5}
                    style={{ ...inputStyle, resize: "vertical", minHeight: 132 }}
                    onFocus={onFocus} onBlur={onBlur}
                  />
                  <p style={{
                    fontSize: 11,
                    fontFamily: "var(--font-mono)",
                    margin: "5px 0 0",
                    textAlign: "right",
                    color: isOverLimit ? "var(--color-red, #f87171)" : "var(--text-faint)",
                    transition: "color 120ms var(--ease-standard)",
                  }}>
                    {charsRemaining} / {MESSAGE_MAX}
                  </p>
                </div>
                {status === "error" && (
                  <p style={{ fontSize: 12, color: "var(--text-muted)", margin: 0 }}>
                    Something went wrong — email me directly at {PROFILE.socials.email}
                  </p>
                )}
                <button
                  type="submit"
                  disabled={status === "loading" || isOverLimit}
                  className="btn-primary"
                  style={{ opacity: status === "loading" || isOverLimit ? 0.7 : 1, cursor: status === "loading" ? "wait" : isOverLimit ? "not-allowed" : "pointer" }}
                >
                  {status === "loading" ? "Sending…" : <>Send Message <span className="btn-arrow">→</span></>}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  )
}
```

**What changed** (surgical diff):

1. `MESSAGE_MAX = 500` constant at the top.
2. Two derived values before the return: `charsRemaining` and `isOverLimit`.
3. A `<p>` counter right after the `<textarea>`, right-aligned, using `var(--font-mono)` and `var(--text-faint)` to match the label style — turns `var(--color-red, #f87171)` when over the limit (with a fallback in case the CSS var isn't defined).
4. The submit button gains `disabled={... || isOverLimit}` and `cursor: "not-allowed"` when over limit, so the form can't be submitted with an invalid message.
